  staticData.cookies = input.cookies;
  staticData.localStorage = input.localStorage;
  staticData.ultimoLogin = new Date().toISOString();
}

return [{ json: input }];

const input = $('4-SalvarSessao').first().json;
const cookies = JSON.stringify(input.cookies || []);
const localStorage = JSON.stringify(input.localStorage || {});

// CODIGO COM CORRECOES DO DEBUG-LOCAL
const code = `export default async function ({ page }) {
  const wait = (ms) => new Promise(r => setTimeout(r, ms));
  const cookies = ${cookies};
  const ls = ${localStorage};
  let debug = [];

  try {
    await page.setViewport({ width: 1280, height: 800 });
    await page.goto('https://app.cotadorsimplificado.com.br/?produto=hap', { waitUntil: 'domcontentloaded', timeout: 60000 });
    if (cookies.length > 0) await page.setCookie(...cookies);
    await page.evaluate((ls) => { for (const [k, v] of Object.entries(ls)) window.localStorage.setItem(k, v); }, ls);
    await page.reload({ waitUntil: 'domcontentloaded', timeout: 60000 });
    await wait(4000);
    debug.push('Pagina carregada');

    // PME
    await page.evaluate(() => {
      const pme = [...document.querySelectorAll('.clickable-element')].find(e => e.textContent.includes('PME') && e.textContent.includes('29'));
      if (pme) pme.click();
    });
    await wait(2000);
    debug.push('PME clicado');

    // Nome
    await page.waitForSelector('#id-nomelead', { timeout: 10000 });
    const nomeInput = await page.$('#id-nomelead');
    if (nomeInput) { await nomeInput.click(); await nomeInput.type('teste', { delay: 20 }); }
    debug.push('Nome preenchido');

    // Avancar 1
    await page.evaluate(() => { const btn = [...document.querySelectorAll('button')].find(b => b.textContent.includes('Avan')); if (btn) btn.click(); });
    await wait(3000);
    debug.push('Avancar 1');

    // CIDADE - CORRECAO: usar page.mouse.click com coordenadas
    await page.waitForSelector('#cidade_nome', { timeout: 10000 });
    const cidadeInput = await page.$('#cidade_nome');
    if (cidadeInput) { await cidadeInput.click(); await wait(500); await cidadeInput.type('teresina', { delay: 100 }); }
    await wait(2000);

    // CORRECAO: Clica no clickable-element com texto exato
    const teresinaCoords = await page.evaluate(() => {
      const clickables = document.querySelectorAll('.clickable-element');
      for (const el of clickables) {
        if (el.textContent.trim() === 'Teresina - PI') {
          const rect = el.getBoundingClientRect();
          if (rect.width > 0 && rect.height > 0) {
            return { x: rect.x + rect.width / 2, y: rect.y + rect.height / 2 };
          }
        }
      }
      return null;
    });
    if (teresinaCoords) {
      await page.mouse.click(teresinaCoords.x, teresinaCoords.y);
      debug.push('Cidade: mouse click OK');
    } else {
      debug.push('Cidade: NAO ENCONTRADA');
    }
    await wait(2000);

    // MEI
    try {
      await page.waitForSelector('select.Dropdown', { timeout: 5000 });
      await page.select('select.Dropdown', '"mei___empres_rio_individual"');
      debug.push('MEI selecionado');
    } catch(e) { debug.push('MEI erro'); }
    await wait(1500);

    // CORRECAO: Avancar 2 - verifica visibilidade
    const btns2 = await page.$$('button');
    for (const btn of btns2) {
      const info = await page.evaluate(el => {
        const s = window.getComputedStyle(el);
        return { t: el.textContent, d: s.display, v: s.visibility };
      }, btn);
      if (info.t && info.t.includes('Avan') && info.d !== 'none' && info.v !== 'hidden') {
        await btn.click();
        debug.push('Avancar 2');
        break;
      }
    }
    await wait(3000);

    // CORRECAO: FAIXAS - placeholder='0' E className.includes('cocys')
    const faixasResult = await page.evaluate(() => {
      let count = 0;
      document.querySelectorAll('input').forEach(inp => {
        const r = inp.getBoundingClientRect();
        const s = window.getComputedStyle(inp);
        const isVisible = r.width > 0 && r.height > 0 && s.display !== 'none' && s.visibility !== 'hidden';
        const isFaixaInput = inp.placeholder === '0' && inp.className.includes('cocys');
        if (isVisible && !inp.id && isFaixaInput) {
          inp.focus(); inp.value = '1';
          inp.dispatchEvent(new Event('input', { bubbles: true }));
          inp.dispatchEvent(new Event('change', { bubbles: true }));
          count++;
        }
      });
      return count;
    });
    debug.push('Faixas: ' + faixasResult);
    await wait(1500);

    // CORRECAO: Avancar 3 - verifica visibilidade
    const btns3 = await page.$$('button');
    for (const btn of btns3) {
      const info = await page.evaluate(el => {
        const s = window.getComputedStyle(el);
        return { t: el.textContent, d: s.display, v: s.visibility };
      }, btn);
      if (info.t && info.t.includes('Avan') && info.d !== 'none' && info.v !== 'hidden') {
        await btn.click();
        debug.push('Avancar 3');
        break;
      }
    }
    await wait(4000);

    // ADD PRODUTOS
    const btns4 = await page.$$('button');
    for (const btn of btns4) {
      const info = await page.evaluate(el => {
        const s = window.getComputedStyle(el);
        return { t: el.textContent.trim(), d: s.display, v: s.visibility };
      }, btn);
      if (info.t === 'Add Produtos' && info.d !== 'none' && info.v !== 'hidden') {
        await btn.click();
        debug.push('Add Produtos');
        break;
      }
    }
    await wait(3000);

    // HAPVIDA no modal
    const hapCoords = await page.evaluate(() => {
      for (const el of document.querySelectorAll('.clickable-element')) {
        if (el.textContent.trim() === 'Hapvida') {
          const r = el.getBoundingClientRect();
          if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 };
        }
      }
      return null;
    });
    if (hapCoords) { await page.mouse.click(hapCoords.x, hapCoords.y); debug.push('Hapvida modal'); }
    await wait(3000);

    // TABELA Teresina
    const tabCoords = await page.evaluate(() => {
      for (const el of document.querySelectorAll('.clickable-element')) {
        const t = el.textContent.trim();
        if (t.includes('Teresina') && t.includes('2') && t.includes('29')) {
          const r = el.getBoundingClientRect();
          if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 };
        }
      }
      return null;
    });
    if (tabCoords) { await page.mouse.click(tabCoords.x, tabCoords.y); debug.push('Tabela Teresina'); }
    await wait(2000);

    // AMBULATORIAL
    const ambCoords = await page.evaluate(() => {
      for (const el of document.querySelectorAll('.clickable-element')) {
        if (el.textContent.trim() === 'Ambulatorial') {
          const r = el.getBoundingClientRect();
          if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 };
        }
      }
      return null;
    });
    if (ambCoords) { await page.mouse.click(ambCoords.x, ambCoords.y); debug.push('Ambulatorial'); }
    await wait(2000);

    // ACOMODACAO
    const acoCoords = await page.evaluate(() => {
      for (const el of document.querySelectorAll('.clickable-element')) {
        const t = el.textContent.trim().toLowerCase();
        if (t.includes('sem acomodação') && t.includes('coparticipação')) {
          const r = el.getBoundingClientRect();
          if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 };
        }
      }
      return null;
    });
    if (acoCoords) { await page.mouse.click(acoCoords.x, acoCoords.y); debug.push('Acomodacao'); }
    await wait(2000);

    // FECHA MODAL
    await page.mouse.click(1200, 400);
    debug.push('Modal fechado');
    await wait(3000);

    // EXTRAI VALORES
    const faixas = await page.evaluate(() => {
      const nomes = ['0 a 18 anos','19 a 23 anos','24 a 28 anos','29 a 33 anos','34 a 38 anos','39 a 43 anos','44 a 48 anos','49 a 53 anos','54 a 58 anos','59 anos ou mais'];
      const vals = [];
      const regex = /^\\d{2,3}[,.]\\d{2}$/;
      document.querySelectorAll('div, span').forEach(el => {
        const s = window.getComputedStyle(el);
        const r = el.getBoundingClientRect();
        if (s.display !== 'none' && r.width > 0 && el.textContent.length < 15) {
          const t = el.textContent.trim();
          if (regex.test(t) && !vals.some(v => v.text === t) && r.y > 650 && r.x > 150 && r.x < 280) {
            vals.push({ text: t, y: r.y });
          }
        }
      });
      vals.sort((a,b) => a.y - b.y);
      return vals.slice(0,10).map((v,i) => ({ faixa_etaria: nomes[i], valor: 'R$ ' + v.text.replace('.',',') }));
    });
    debug.push('Faixas extraidas: ' + faixas.length);

    return { success: true, fase: 'COMPLETO', faixas, debug };
  } catch (error) {
    return { success: false, fase: 'ERRO', error: error.message, debug };
  }
}`;

return [{ json: { code } }];
